china_us_business_baggage_total_calculat.procedure:
def apply(inputs, premises):
    checked = []
    personal_used = False
    carryon_used = False
    for i in range(len(inputs["lengths"])):
        fits_personal = inputs["lengths"][i] <= premises["personal_limits"][0] and inputs["widths"][i] <= premises["personal_limits"][1] and inputs["heights"][i] <= premises["personal_limits"][2]
        fits_carryon = inputs["lengths"][i] <= premises["carryon_limits"][0] and inputs["widths"][i] <= premises["carryon_limits"][1] and inputs["heights"][i] <= premises["carryon_limits"][2]
        if fits_personal and not personal_used:
            personal_used = True
        elif fits_carryon and not carryon_used:
            carryon_used = True
        else:
            checked = checked + [i]
    fees = 0
    for position in range(len(checked)):
        if position >= premises["complimentary_checked_count"]:
            fees = fees + premises["third_and_later_checked_fee"]
        item = checked[position]
        weight_fee = 0
        if inputs["weights"][item] > premises["business_weight_limit"]:
            for j in range(len(premises["overweight_upper_bounds"])):
                if inputs["weights"][item] <= premises["overweight_upper_bounds"][j]:
                    weight_fee = premises["overweight_fees"][j]
                    break
        dimension = inputs["lengths"][item] + inputs["widths"][item] + inputs["heights"][item]
        size_fee = 0
        if dimension > premises["standard_dimension_limit"]:
            for j in range(len(premises["oversize_upper_bounds"])):
                if dimension <= premises["oversize_upper_bounds"][j]:
                    size_fee = premises["oversize_fees"][j]
                    break
        fees = fees + max(weight_fee, size_fee)
    return {"answer": int(inputs["ticket_price"] + fees)}

progressive_tax_bracket_claim_classifier.procedure:
def apply(inputs, premises):
    applicable_index = -1
    for i in range(len(inputs["bracket_lower_bounds"])):
        above_lower = inputs["taxable_income"] > inputs["bracket_lower_bounds"][i] or inputs["bracket_lower_bounds"][i] == 0
        below_upper = inputs["bracket_upper_bounds"][i] < 0 or inputs["taxable_income"] <= inputs["bracket_upper_bounds"][i]
        if above_lower and below_upper:
            applicable_index = i + 1
            break
    correct = inputs["filing_status_matches_schedule"] and applicable_index == inputs["claimed_bracket_index"]
    if correct:
        i = applicable_index - 1
        computed_tax = inputs["bracket_base_amounts"][i] + inputs["bracket_rates"][i] * (inputs["taxable_income"] - inputs["bracket_lower_bounds"][i])
        correct = abs(computed_tax - inputs["claimed_tax_amount"]) <= 0.005
    if correct:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}

